// Recupere le token envoye par le template UI (cote client)
// msg._client est preserve automatiquement (on ne le touche pas)
const token = msg.payload && msg.payload.token;

if (!token) {
    msg.payload = { error: true, message: "Lien invalide ou expire." };
    return [null, msg];
}

flow.set('lookup_token', token);

msg.payload = [
    {
        $match: {
            token: token,
            statut: "ouverte"
        }
    },
    {
        $lookup: {
            from: "commandes",
            localField: "_id",
            foreignField: "visiteId",
            as: "commandes"
        }
    },
    {
        $project: {
            tableNumero: 1,
            badgeId: 1,
            clientId: 1,
            dateArrivee: 1,
            montantTotalVisite: 1,
            commandes: 1
        }
    }
];

return [msg, null];

const visite = msg.payload[0];

global.set("visitId", visite._id);

if (!visite) {
    msg.payload = { error: true, message: "Aucune visite trouvee pour ce token." };
    return msg;
}

msg.payload = {
    tableNumero: visite.tableNumero,
    dateArrivee: visite.dateArrivee,
    montantTotal: visite.montantTotalVisite,
    commandes: (visite.commandes || []).map(function(cmd) {
        return {
            statut: cmd.statut || "En attente",
            articles: cmd.articles || []
        };
    })
};

return msg;
